@Override
public long readLong(final int offset) {
    // Step 1: Check if the offset is valid
    if (offset < 0 || offset > this.code.length) {
        throw new IllegalArgumentException("Invalid offset: " + offset);
    }

    // Step 2: Read the value from the offset
    long value = 0;
    for (int i = 0; i < 8; i++) {
        value |= (this.code[offset + i] & 0xFFL) << (8 * i);
    }

    // Step 3: Check if the value is negative
    if (value < 0) {
        value ^= Long.MIN_VALUE;
    }

    return value;
}

