ByteVector putByteArray(final byte[] byteArrayValue, final int byteOffset, final int byteLength) {
    if (byteArrayValue == null) {
        // If the input array is null, we still need to enlarge the byte vector.
        enlarge(byteLength);
        for (int i = 0; i < byteLength; i++) {
            // Put null bytes into the byte vector.
            data[length++] = 0;
        }
    } else {
        // If the input array is not null, enlarge the byte vector and copy the input array.
        enlarge(byteLength);
        System.arraycopy(byteArrayValue, byteOffset, data, length, byteLength);
        length += byteLength;
    }
    return this;
}

