int addConstantNameAndType(final String name, final String descriptor) {
    // Check if the constant pool already contains a similar item
    for (int i = 0; i < constantPool.getSize(); i++) {
        Constant constant = constantPool.get(i);
        if (constant instanceof ConstantNameAndType) {
            ConstantNameAndType nameAndType = (ConstantNameAndType) constant;
            if (nameAndType.getName().equals(name) && nameAndType.getDescriptor().equals(descriptor)) {
                return i; // The constant pool already contains a similar item
            }
        }
    }

    // Create a new ConstantNameAndType item and add it to the constant pool
    ConstantNameAndType nameAndType = new ConstantNameAndType(name, descriptor);
    return constantPool.add(nameAndType);
}

