public static <V, E> boolean isClique(Graph<V, E> graph, Set<V> vertices) {
    // create a new graph with the same vertices as the input graph
    Graph<V, E> subgraph = Graphs.copyOf(graph);

    // add the edges between the vertices in the input graph
    for (V vertex : vertices) {
        for (V neighbor : graph.neighborsOf(vertex)) {
            if (vertices.contains(neighbor)) {
                subgraph.addEdge(vertex, neighbor);
            }
        }
    }

    // check if the subgraph is connected and has no isolated vertices
    return subgraph.isConnected() && subgraph.isSimple();
}

