public static List<ThreadSnapshot> parseFromFileWithTimeRange(File file, List<ProfileAncodeAnalyzeTimeRange> timeRanges) throws IOException {
	List<ThreadSnapshot> snapshots = new ArrayList<>();

	// Check if the file is valid
	if (!file.exists() || !file.canRead()) {
		throw new FileNotFoundException(file.getPath() + " does not exist or cannot be read");
	}

	// Check if the timeRanges are valid
	if (timeRanges.isEmpty()) {
		throw new IOException("No time ranges provided");
	}

	// Parse the file
	BufferedReader reader = new BufferedReader(new FileReader(file));
	String line;
	while ((line = reader.readLine()) != null) {
		// Parse the line
		String[] parts = line.split(",");

		// Check if the line contains a thread snapshot
		if (parts.length < 2) {
			continue;
		}

		// Get the time range
		long timestamp = Long.parseLong(parts[0]);
		timeRange.add(timestamp);

		// Check if the timestamp is within the allowed time range
		boolean inRange = false;
		for (ProfileAncodeAnalyzeTimeRange range : timeRanges) {
			if (timestamp >= range.getStartTime() && timestamp <= range.getEndTime()) {
				inRange = true;
				break;
			}
		}

		// Add the snapshot to the list
		if (inRange) {
			snapshots.add(new ThreadSnapshot(file, timestamp));
		}
	}

	reader.close();

	return snapshots;
}

