     * Implementation plan:
     * 1. Check if the descriptor is a method descriptor. If it is, we need to pop its argument types in addition to its return type.
     * 2. Find the return type of the method, and pop it from the output frame stack.
     * 3. If the descriptor has method arguments, pop each of them from the stack as well.
     */

    final boolean isMethodDescriptor = descriptor.startsWith("(");
    final int returnTypeStartIndex = isMethodDescriptor ? descriptor.lastIndexOf(")") + 1 : 0;
    final String returnType = descriptor.substring(returnTypeStartIndex);

    // Pop the return type off the stack
    popOff(returnType);

    if (isMethodDescriptor) {
        // Calculate the number of method arguments
        final int argumentCount = getArgumentCount(descriptor);

        // Pop each argument type off the stack
        for (int i = 0; i < argumentCount; i++) {
            popOff(getArgumentType(descriptor, i));
        }
    }
}

