    int length = schema.getSerializedSize(message);
    int totalLength = 4 + length;
    if (buffer.readableBytes() < totalLength) {
        // Buffer is not large enough to hold the entire message
        // Allocate a new buffer
        buffer = buffer.alloc().allocate(totalLength);
    }
    // Write the message length
